async function refreshSession(){const {data}=await sb.auth.getSession();state.user=data.session?{...data.session.user,access_token:data.session.access_token}:null;if(state.user){try{await helperCoreApi('resolve')}catch(e){console.error('Helper Core identity resolve failed',e);state.helperCore=null}try{const b=await api('bootstrap');state.roles=b.user?.roles||['user']}catch{state.roles=['user']}state.mode=preferredMode();if(state.helperCore?.needs_nickname&&!nicknamePrompting)setTimeout(()=>openNicknameSetup(true),250)}else{state.helperCore=null;state.roles=['user'];state.mode='user'}syncTopbar()}
