function openNicknameSetup(required=false){if(!state.user||nicknamePrompting)return;nicknamePrompting=true;openModal(`<div class="loginPanel"><span class="eyebrow">HELPER NICKNAME</span><h2>헬퍼유니버스 닉네임 설정</h2><p>이 닉네임은 모든 헬퍼 플랫폼에서 동일하게 사용됩니다. 중복·공식계정 사칭 닉네임은 사용할 수 없습니다.</p><div class="field"><label>닉네임</label><input id="globalNicknameInput" maxlength="20" placeholder="2~20자" value="${state.helperCore?.nickname||''}"></div><p class="muted small">변경 이력이 보존되며, 설정 후 변경에는 30일 제한이 적용됩니다.</p><button id="saveGlobalNickname" class="submitBtn">닉네임 저장</button>${required?'<p class="modeNotice">채팅·회원 공개 기능에서는 닉네임 설정이 필요합니다.</p>':''}</div>`);const finish=()=>{nicknamePrompting=false};const close=$('#modalClose');if(close){close.onclick=()=>{finish();closeModal()}}$('#saveGlobalNickname').onclick=async()=>{const nickname=String($('#globalNicknameInput')?.value||'').trim();if(!nickname)return toast('닉네임을 입력해 주세요.');try{await helperCoreApi('set_nickname',{nickname});toast('헬퍼유니버스 닉네임이 저장되었습니다.');finish();closeModal();syncTopbar();render()}catch(e){const code=e?.data?.error||e?.message||'';const msg=code.includes('TAKEN')?'이미 사용 중인 닉네임입니다.':code.includes('RESERVED')?'공식 계정·운영자와 혼동될 수 있는 닉네임입니다.':code.includes('COOLDOWN')?'닉네임은 최근 변경 후 30일이 지나야 다시 바꿀 수 있습니다.':'닉네임을 저장하지 못했습니다.';toast(msg)}}}
async function linkHelperProvider(provider){if(!state.user)return openLogin();try{const linked=state.helperCore?.linked_providers||[];if(linked.includes(provider))return toast('이미 연결된 계정입니다.');const {error}=await sb.auth.linkIdentity({provider,options:{redirectTo:AUTH_RETURN_URL}});if(error)throw error}catch(e){console.error(e);toast('계정 연결을 시작하지 못했습니다. 관리자에게 문의해 주세요.')}}
function openAccount(){const types=['user','host','supplier','operator'].filter(canUseMode),hostStart=!state.roles.includes('host'),supplierStart=!state.roles.includes('supplier'),hc=state.helperCore||{},providers=hc.linked_providers||[];openModal(`<div class="loginPanel"><span class="eyebrow">MY LIFEHELPER</span><h2>${hc.nickname||'닉네임 미설정'}</h2><p><b>${hc.helper_code||'Helper ID 확인 중'}</b><br>헬퍼유니버스 전체에서 사용하는 회원 ID입니다.</p><p>가입·승인 유형: ${types.map(r=>ROLE_META[r].label).join(' · ')}</p><p class="muted small">본인인증 연결: ${providers.map(x=>x==='google'?'Google':x==='kakao'?'Kakao':x).join(' · ')||'확인 중'}</p><button id="nicknameBtn" class="oauth google">${hc.nickname?'전역 닉네임 변경':'전역 닉네임 설정'}</button>${!providers.includes('google')?'<button id="linkGoogleBtn" class="oauth google">Google 계정 연결</button>':''}${!providers.includes('kakao')?'<button id="linkKakaoBtn" class="oauth kakao">Kakao 계정 연결</button>':''}${types.length>1?'<button id="accountModeSwitch" class="oauth google">이용 유형 전환</button>':''}${hostStart?'<button id="startHostBtn" class="oauth google">호스트로 시작하기</button>':''}${supplierStart?'<button id="startSupplierBtn" class="oauth google">공급자 등록 신청</button>':''}<button id="logoutBtn" class="oauth google">로그아웃</button></div>`);$('#nicknameBtn').onclick=()=>{closeModal();setTimeout(()=>openNicknameSetup(false),50)};const lg=$('#linkGoogleBtn');if(lg)lg.onclick=()=>linkHelperProvider('google');const lk=$('#linkKakaoBtn');if(lk)lk.onclick=()=>linkHelperProvider('kakao');const ms=$('#accountModeSwitch');if(ms)ms.onclick=()=>{closeModal();openModeSwitcher()};const hs=$('#startHostBtn');if(hs)hs.onclick=()=>{closeModal();openRoleApplication('host')};const ss=$('#startSupplierBtn');if(ss)ss.onclick=()=>{closeModal();openRoleApplication('supplier')};$('#logoutBtn').onclick=async()=>{await sb.auth.signOut();localStorage.removeItem('lifehelper.last_mode');closeModal();await refreshSession();render()}}
