function openPublicB2B(){openModal(`<div><span class="eyebrow">GROUP · B2B INQUIRY</span><h2>단체·기업 숙박 문의</h2><p class="muted">로그인하지 않아도 요청할 수 있습니다. 실제 재고와 조건을 확인한 뒤 제안합니다.</p><form id="publicB2BForm" class="formGrid"><div class="field"><label>기업/단체명 *</label><input name="company_name" required></div><div class="field"><label>담당자 *</label><input name="contact_name" required></div><div class="field"><label>전화 *</label><input name="phone" required></div><div class="field"><label>이메일 *</label><input name="email" type="email" required></div><div class="field"><label>시작일 *</label><input name="start_date" type="date" required></div><div class="field"><label>종료일 *</label><input name="end_date" type="date" required></div><div class="field"><label>인원 *</label><input name="group_size" type="number" min="1" required></div><div class="field"><label>희망 지역</label><input name="area"></div><div class="field full"><label>요청사항</label><textarea name="notes" placeholder="객실 구성, 예산, 일정, 이동 등"></textarea></div><div class="field full"><label class="consent"><input type="checkbox" name="consent" required>단체 견적 상담을 위해 담당자 정보를 처리하는 데 동의합니다.</label></div><div class="field full"><button class="submitBtn" type="submit">단체 문의 보내기 →</button></div></form></div>`);const b2bForm=$('#publicB2BForm');const today=new Date().toISOString().slice(0,10);b2bForm.start_date.min=today;b2bForm.end_date.min=today;b2bForm.start_date.addEventListener('change',()=>{b2bForm.end_date.min=b2bForm.start_date.value||today;if(b2bForm.end_date.value&&b2bForm.end_date.value<=b2bForm.start_date.value)b2bForm.end_date.value=''});b2bForm.onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(!e.currentTarget.consent.checked)return toast('개인정보 처리 동의를 확인해 주세요.');if(String(f.get('end_date'))<=String(f.get('start_date')))return toast('종료일은 시작일 이후로 선택해 주세요.');const payload={privacy_accepted:true,helper_id:helperId(),company_name:String(f.get('company_name')),event_name:'',contact_name:String(f.get('contact_name')),phone:String(f.get('phone')),email:String(f.get('email')),purpose:'business',start_date:String(f.get('start_date')),end_date:String(f.get('end_date')),group_size:Number(f.get('group_size')),budget_per_person:null,area:String(f.get('area')||''),country_language:'',services:['stay'],notes:String(f.get('notes')||'')};try{await b2bApi(payload);toast('단체 문의가 접수되었습니다.');closeModal()}catch{toast('단체 문의를 저장하지 못했습니다.')}}}
function purposeSection(){return `<section class="purposeBar"><div class="purposeTitle"><div><span class="eyebrow">WHY KOREA?</span><h2>왜 한국에 오시나요?</h2><p>방문 목적을 먼저 고르면 숙소 추천 기준이 달라집니다.</p></div></div><div class="purposeGrid">${purposes.map(p=>`<button class="purposeCard ${state.purpose===p.id?'active':''}" data-purpose="${p.id}"><span class="purposeIcon">${p.icon}</span><b>${state.lang==='ko'?p.ko:p.en}</b><span>${p.desc}</span></button>`).join('')}</div></section>`}
function journeySection(){const s=[['목적 선택','방문 이유를 선택합니다.'],['일정 확인','날짜·인원·예산을 입력합니다.'],['추천 숙소','조건에 맞는 후보를 봅니다.'],['예약/요청','바로 예약 또는 요청합니다.'],['체험 추가','숙박 이후 필요한 경험을 더합니다.'],['내 일정','숙소와 체험을 하나의 일정으로 봅니다.']];return `<section class="journey"><div class="journeyBox">${s.map((x,i)=>`<div class="journeyStep"><b><i>${i+1}</i>${x[0]}</b><span>${x[1]}</span></div>`).join('')}</div></section>`}
function requestBuilder(){return `<section class="section" id="requestBuilder"><div class="sectionHead"><div><span class="eyebrow">STAY MATCHING</span><h2>일정과 조건을 알려주세요.</h2><p>실제 공개 가능 숙소를 기준으로 후보를 좁히고 요청을 저장합니다.</p></div><button class="secondaryBtn" id="myJourneyBtn">내 요청·일정 보기</button></div><div class="requestBuilder"><form class="formPanel" id="stayForm"><div class="formGrid"><div class="field"><label>방문 목적</label><select name="purpose">${purposes.map(p=>`<option value="${p.id}" ${p.id===state.purpose?'selected':''}>${p.ko}</option>`).join('')}</select></div><div class="field"><label>행사/기관명</label><input name="event_name" placeholder="예: 서울 국제행사 2026"></div><div class="field"><label>체크인 *</label><input name="check_in" type="date" required></div><div class="field"><label>체크아웃 *</label><input name="check_out" type="date" required></div><div class="field"><label>인원 *</label><input name="guests" type="number" min="1" max="5000" placeholder="예: 12" required></div><div class="field"><label>희망 지역</label><input name="area" placeholder="예: 서울 중구"></div><div class="field"><label>1인/총 최소 예산</label><input name="budget_min" inputmode="numeric" placeholder="예: 100000"></div><div class="field"><label>최대 예산</label><input name="budget_max" inputmode="numeric" placeholder="예: 200000"></div><div class="field full"><label>객실·침대·단체 조건</label><input name="room_needs" placeholder="예: 2인실, 싱글베드 2개, 여성 참가자 중심"></div><div class="field"><label>담당자 이름 *</label><input name="contact_name" required></div><div class="field"><label>기관/회사</label><input name="organization"></div><div class="field"><label>연락처</label><input name="contact_phone" placeholder="전화·메신저"></div><div class="field"><label>이메일</label><input name="contact_email" type="email"></div><div class="field full"><label>추가 요청</label><textarea name="special_requests" placeholder="짐 보관, 조식, 이동, 장기숙박 등"></textarea></div></div><div class="checkRow"><button type="button" class="chipCheck active" data-lang="ko">한국어</button><button type="button" class="chipCheck" data-lang="en">English</button><button type="button" class="chipCheck" data-lang="ja">日本語</button><button type="button" class="chipCheck" data-lang="zh">中文</button></div><label class="consent"><input type="checkbox" name="consent" required>숙박 매칭 상담을 위해 입력한 정보를 처리하는 데 동의합니다.</label><button class="submitBtn" type="submit">숙박 요청 보내기 →</button></form><div class="resultPanel"><div class="resultToolbar"><b>추천 숙소</b><span class="muted small" id="spaceCount">불러오는 중</span></div><div id="spaceList" class="spaceList"><div class="loading">실제 숙소 데이터를 확인하는 중입니다.</div></div><div class="compareDock" id="compareDock"><div class="compareItems" id="compareItems"></div><button class="primaryBtn" id="compareBtn">비교하기</button></div></div></div></section>`}
function matchScore(space,form={}){let score=45;if(space.verified)score+=18;if(space.inventory_fresh)score+=15;if(form.guests&&space.capacity>=Number(form.guests))score+=12;if(form.area&&space.location?.includes(form.area))score+=8;if(space.purpose_tags?.includes(state.purpose))score+=10;return Math.min(score,100)}
function filteredSpaces(){const f=new FormData($('#stayForm')||document.createElement('form'));const guests=Number(f.get('guests')||0),area=String(f.get('area')||'');return state.spaces.filter(s=>(!guests||s.capacity>=guests)&&(!area||String(s.location||'').includes(area))).sort((a,b)=>matchScore(b,{guests,area})-matchScore(a,{guests,area}))}
function renderSpaces(){const list=$('#spaceList');if(!list)return;const spaces=filteredSpaces();$('#spaceCount').textContent=`${spaces.length}곳 · 실제 공개 가능 숙소 기준`;if(!spaces.length){list.innerHTML='<div class="empty"><div><b>현재 조건에 맞는 공개 숙소가 없습니다.</b><p>조건을 조금 넓히거나 요청을 보내면 운영자가 실제 재고를 확인해 제안합니다.</p></div></div>';return}list.innerHTML=spaces.map(s=>`<article class="spaceCard" data-space="${s.id}"><div class="spaceImg" style="background-image:url('${s.public_image||'https://images.unsplash.com/photo-1566665797739-1674de7a421a?auto=format&fit=crop&w=900&q=80'}')"></div><div class="spaceBody"><div class="spaceTop"><div><h3>${s.name}</h3><span class="muted small">${s.location||'지역 확인 중'}</span></div><b>${matchScore(s,{guests:Number(new FormData($('#stayForm')).get('guests')||0),area:String(new FormData($('#stayForm')).get('area')||'')})}% 적합</b></div><div class="badges"><span class="badge ${s.verified?'good':'warn'}">${s.verified?'검증 숙소':'검증 확인 필요'}</span><span class="badge ${s.inventory_fresh?'good':'warn'}">${s.inventory_fresh?'48시간 내 재고 확인':'재고 재확인 필요'}</span>${s.allows_long_stay?'<span class="badge blue">장기숙박 가능</span>':''}${s.allow_foreign?'<span class="badge blue">외국인 가능</span>':''}</div><div class="spaceMeta"><span>인원 <b>${s.min_guests||1}~${s.capacity||'문의'}명</b></span><span>객실 <b>${s.room_type||s.room_count?`${s.room_type||''} ${s.room_count||''}`:'상세 확인'}</b></span><span>가격 <b>${money(s.per_person_price)}</b></span><span>언어 <b>${(s.supported_languages||['ko']).join(', ').toUpperCase()}</b></span><span>예약 <b>${({instant:'즉시 예약',request:'요청 후 확정',contract:'협의·계약'})[s.booking_mode]||'요청'}</b></span><span>단체 <b>${s.allows_group?'가능':'문의'}</b></span></div><div class="cardActions"><button data-detail="${s.id}">상세 보기</button><button data-compare="${s.id}">${state.compare.includes(s.id)?'비교 해제':'비교'}</button><button data-save="${s.id}">저장</button><button class="primary" data-request-space="${s.id}">이 숙소로 요청</button></div></div></article>`).join('');bindSpaceActions();renderCompareDock()}
function bindSpaceActions(){$$('[data-detail]').forEach(b=>b.onclick=()=>openSpaceDetail(b.dataset.detail));$$('[data-compare]').forEach(b=>b.onclick=()=>toggleCompare(b.dataset.compare));$$('[data-save]').forEach(b=>b.onclick=()=>saveSpace(b.dataset.save));$$('[data-request-space]').forEach(b=>b.onclick=()=>{const s=state.spaces.find(x=>x.id===b.dataset.requestSpace);if(s){$('#stayForm [name=area]').value=s.location||'';$('#stayForm [name=room_needs]').value=`선호 숙소: ${s.name}`;$('#requestBuilder').scrollIntoView({behavior:'smooth'});toast('선호 숙소를 요청 조건에 반영했습니다.')}})}
function toggleCompare(id){if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<3)state.compare.push(id);else return toast('비교는 최대 3곳까지 가능합니다.');renderSpaces()}
function renderCompareDock(){const dock=$('#compareDock');if(!dock)return;dock.classList.toggle('show',state.compare.length>0);$('#compareItems').innerHTML=state.compare.map(id=>`<span class="compareItem">${state.spaces.find(s=>s.id===id)?.name||'숙소'}</span>`).join('');$('#compareBtn').onclick=openCompare}
async function saveSpace(id){if(!state.user)return openLogin();try{await api('save_space',{space_id:id,saved:true});toast('저장했습니다.')}catch(e){toast('저장하지 못했습니다.')}}
function openSpaceDetail(id){const s=state.spaces.find(x=>x.id===id);if(!s)return;openModal(`<div><span class="eyebrow">STAY DETAIL</span><h2>${s.name}</h2><p class="muted">${s.location||''}</p><div class="spaceImg" style="min-height:280px;border-radius:14px;background-image:url('${s.public_image||'https://images.unsplash.com/photo-1566665797739-1674de7a421a?auto=format&fit=crop&w=1000&q=80'}')"></div><div class="badges"><span class="badge ${s.verified?'good':'warn'}">${s.verified?'검증 상태 확인':'검증 확인 필요'}</span><span class="badge ${s.inventory_fresh?'good':'warn'}">${s.inventory_fresh?'최근 재고 확인':'재고 재확인 필요'}</span></div><div class="spaceMeta"><span>수용인원 <b>${s.capacity||'문의'}명</b></span><span>객실유형 <b>${s.room_type||'확인 필요'}</b></span><span>객실수 <b>${s.room_count||'확인 필요'}</b></span><span>1인 기준 <b>${money(s.per_person_price)}</b></span><span>지원언어 <b>${(s.supported_languages||['ko']).join(', ').toUpperCase()}</b></span><span>예약방식 <b>${({instant:'즉시 예약',request:'요청 후 확정',contract:'협의·계약'})[s.booking_mode]||'요청 후 확정'}</b></span><span>목적지 거리 <b>요청·제안 시 확인</b></span><span>체크인/아웃 <b>제안 시 확인</b></span></div><h3>시설</h3><p>${(s.amenities||[]).join(' · ')||'세부 시설은 요청 과정에서 확인합니다.'}</p><h3>검증·예약 안내</h3><p>${s.verification_summary||'숙소의 영업·운영 상태와 실제 재고는 예약 확정 전에 다시 확인합니다.'}</p><p class="modeNotice">취소·환불 기준과 최종 금액은 숙소 제안 단계에서 확인해 동의한 뒤 진행합니다. 현재 정보만으로 예약이 확정되지는 않습니다.</p><div class="cardActions"><button id="detailCompare">비교 담기</button><button class="primary" id="detailRequest">이 숙소로 요청</button></div></div>`);$('#detailCompare').onclick=()=>{toggleCompare(id);closeModal()};$('#detailRequest').onclick=()=>{closeModal();const f=$('#stayForm');if(f){f.area.value=s.location||'';f.room_needs.value=`선호 숙소: ${s.name}`;f.scrollIntoView({behavior:'smooth'})}}}
function openCompare(){const items=state.compare.map(id=>state.spaces.find(s=>s.id===id)).filter(Boolean);if(!items.length)return;openModal(`<div><span class="eyebrow">COMPARE</span><h2>숙소 비교</h2><div class="tableWrap"><table class="table"><thead><tr><th>항목</th>${items.map(s=>`<th>${s.name}</th>`).join('')}</tr></thead><tbody><tr><td>지역</td>${items.map(s=>`<td>${s.location||'—'}</td>`).join('')}</tr><tr><td>수용인원</td>${items.map(s=>`<td>${s.capacity||'—'}명</td>`).join('')}</tr><tr><td>가격</td>${items.map(s=>`<td>${money(s.per_person_price)}</td>`).join('')}</tr><tr><td>지원언어</td>${items.map(s=>`<td>${(s.supported_languages||['ko']).join(', ').toUpperCase()}</td>`).join('')}</tr><tr><td>장기숙박</td>${items.map(s=>`<td>${s.allows_long_stay?'가능':'문의'}</td>`).join('')}</tr><tr><td>검증</td>${items.map(s=>`<td>${s.verified?'확인':'추가 확인'}</td>`).join('')}</tr><tr><td>재고</td>${items.map(s=>`<td>${s.inventory_fresh?'최근 확인':'재확인 필요'}</td>`).join('')}</tr></tbody></table></div></div>`)}
async function submitStayForm(e){e.preventDefault();const f=new FormData(e.currentTarget);if(!f.get('check_in')||!f.get('check_out')||!f.get('guests')||!f.get('contact_name')||!e.currentTarget.consent.checked)return toast('필수 항목과 개인정보 동의를 확인해 주세요.');if(!f.get('contact_phone')&&!f.get('contact_email'))return toast('연락 가능한 전화 또는 이메일 중 하나를 입력해 주세요.');const checkIn=String(f.get('check_in')),checkOut=String(f.get('check_out')),today=new Date().toISOString().slice(0,10);if(checkIn<today)return toast('체크인은 오늘 이후 날짜로 선택해 주세요.');if(checkOut<=checkIn)return toast('체크아웃은 체크인 이후 날짜로 선택해 주세요.');const budgetMin=Number(f.get('budget_min')||0),budgetMax=Number(f.get('budget_max')||0);if(budgetMin&&budgetMax&&budgetMin>budgetMax)return toast('최대 예산은 최소 예산보다 크게 입력해 주세요.');const langs=$$('[data-lang].active').map(b=>b.dataset.lang);if(!langs.length)return toast('응대 가능한 언어를 1개 이상 선택해 주세요.');const payload={helper_id:helperId(),purpose:String(f.get('purpose')),event_name:String(f.get('event_name')||''),check_in:String(f.get('check_in')),check_out:String(f.get('check_out')),guests:Number(f.get('guests')),area:String(f.get('area')||''),budget_min:Number(f.get('budget_min')||0)||null,budget_max:Number(f.get('budget_max')||0)||null,room_needs:String(f.get('room_needs')||''),contact_name:String(f.get('contact_name')),organization:String(f.get('organization')||''),contact_phone:String(f.get('contact_phone')||''),contact_email:String(f.get('contact_email')||''),languages:langs,special_requests:String(f.get('special_requests')||''),privacy_accepted:true};try{const r=await api('create_request',{payload});state.recentRequest=r.request;localStorage.setItem('lifehelper.request.'+r.request.id,r.request.manage_token);toast('숙박 요청이 접수되었습니다.');openRequestSuccess(r.request)}catch(err){toast(err.status===400?'입력값을 다시 확인해 주세요.':'요청 저장에 실패했습니다.')}}
function openRequestSuccess(r){openModal(`<div><span class="eyebrow">REQUEST RECEIVED</span><h2>숙박 요청이 접수됐습니다.</h2><p>현재 상태: <span class="status requested">요청접수</span></p><div class="journeyBox" style="grid-template-columns:repeat(4,1fr)"><div class="journeyStep"><b><i>1</i>요청접수</b><span>조건을 저장했습니다.</span></div><div class="journeyStep"><b><i>2</i>제안중</b><span>가능 숙소를 확인합니다.</span></div><div class="journeyStep"><b><i>3</i>예약협의</b><span>객실·가격·취소조건을 확인합니다.</span></div><div class="journeyStep"><b><i>4</i>예약확정</b><span>최종 동의 후 확정됩니다.</span></div></div><p class="modeNotice">요청 접수는 예약 확정이 아닙니다. 실제 재고와 조건 확인 후 제안을 드립니다.</p><button id="successJourney" class="primaryBtn">내 요청 보기</button></div>`);$('#successJourney').onclick=()=>{closeModal();openMyJourney()}}
async function cancelStayRequest(requestId){const reason=String(prompt('숙박 요청 취소 사유를 입력해 주세요.','일정 변경')||'').trim();if(!reason)return;if(!confirm('이 숙박 요청을 취소할까요?'))return;try{const manage_token=localStorage.getItem('lifehelper.request.'+requestId)||'';await api('cancel_request',{request_id:requestId,manage_token,reason});toast('숙박 요청을 취소했습니다.');openMyJourney()}catch(e){console.error(e);if(e?.data?.error==='paid_reservation_cancel_via_trip'){toast('결제 완료 예약은 내 일정에서 취소·환불해 주세요.');closeModal();setTimeout(openItinerary,80)}else toast(e?.message||'요청 취소에 실패했습니다.')}}
async function openMyJourney(){try{let requests=[];if(state.user){requests=(await api('my_requests')).requests||[]}else{const ids=Object.keys(localStorage).filter(k=>k.startsWith('lifehelper.request.')).map(k=>k.replace('lifehelper.request.',''));if(!ids.length)return openModal('<div><h2>저장된 요청이 없습니다.</h2><p class="muted">숙박 요청을 보내면 현재 상태와 제안을 여기서 확인할 수 있습니다.</p></div>');requests=ids.map(id=>({id,status:id===state.recentRequest?.id?state.recentRequest.status:'requested',created_at:null,purpose:'',check_in:'',check_out:'',guests:''}))}openModal(`<div><span class="eyebrow">MY JOURNEY</span><h2>내 요청·일정</h2><div class="cardActions" style="margin:8px 0 14px"><button class="primary" id="openItineraryBtn">확정 숙박·결제·체험 일정 보기</button></div><div id="journeyList">${requests.map(r=>`<article class="panel" style="margin-top:10px"><div class="panelHead"><div><b>${purposeLabel(r.purpose)||'숙박 요청'}</b><p class="muted small">${r.check_in||''} ${r.check_out?'→ '+r.check_out:''} ${r.guests?`· ${r.guests}명`:''}</p></div><span class="status ${r.status}">${statusText(r.status)}</span></div><div class="cardActions">${!['cancelled','completed'].includes(r.status)?`<button data-view-proposals="${r.id}">숙소 제안 보기</button>`:''}${['requested','proposing','negotiating','confirmed'].includes(r.status)?`<button data-cancel-request="${r.id}">요청 취소</button>`:''}</div></article>`).join('')}</div></div>`);$$('[data-view-proposals]').forEach(b=>b.onclick=()=>openProposals(b.dataset.viewProposals));$$('[data-cancel-request]').forEach(b=>b.onclick=()=>cancelStayRequest(b.dataset.cancelRequest));const itBtn=$('#openItineraryBtn');if(itBtn)itBtn.onclick=openItinerary}catch(e){console.error(e);toast('요청 정보를 불러오지 못했습니다.')}}
async function startReservationPayment(reservationId){
  if(!state.user)return openLogin();
  try{
    const [itinerary,trips]=await Promise.all([itineraryApi('dashboard'),marketplaceApi('my_trips')]);
    const reservation=(trips.reservations||[]).find(r=>r.id===reservationId);
    const checkin=reservation?.checkin?new Date(reservation.checkin+'T00:00:00'):null;
    const checkoutDate=reservation?.checkout?new Date(reservation.checkout+'T23:59:59'):null;
    const selectedExperiences=(itinerary.items||[]).filter(x=>x.item_type==='experience'&&x.meta?.slot_id&&x.reference_id&&x.meta?.booking_status!=='confirmed'&&(!checkin||!checkoutDate||(new Date(x.starts_at)>=checkin&&new Date(x.starts_at)<=checkoutDate))).map(x=>({experience_id:x.reference_id,slot_id:x.meta.slot_id,guest_count:Number(reservation?.guests||1)}));
    const prep=await marketplaceApi('prepare',{reservation_id:reservationId,experiences:selectedExperiences,attribution:{source:'lifehelper_v2',purpose:state.purpose}});
    const checkout=prep.checkout||{},payment=prep.payment||{};
    if(!payment.ready||!payment.clientKey)throw new Error('결제 설정을 확인 중입니다.');
    if(!window.TossPayments)throw new Error('토스 결제 모듈을 불러오지 못했습니다.');
    sessionStorage.setItem('lifehelper.pay.bundleId',checkout.bundle_id||'');
    sessionStorage.setItem('lifehelper.pay.reservationId',reservationId);
    const customerKey='lh_'+String(state.user.id||'').replaceAll('-','').slice(0,40);
    const toss=window.TossPayments(payment.clientKey);
    const pay=toss.payment({customerKey});
    await pay.requestPayment({
      method:'CARD',
      amount:{currency:'KRW',value:Number(checkout.amount||0)},
      orderId:String(checkout.order_id),
      orderName:'라이프헬퍼 숙박 예약',
      customerName:state.helperCore?.nickname||state.user.user_metadata?.name||'라이프헬퍼 게스트',
      customerEmail:state.user.email||undefined,
      successUrl:location.origin+location.pathname+'?lhpay=success',
      failUrl:location.origin+location.pathname+'?lhpay=fail'
    });
  }catch(e){
    console.error(e);
    toast(e?.message||'결제를 시작하지 못했습니다.');
  }
}
async function handleMarketplacePaymentReturn(){
  const q=new URLSearchParams(location.search),mode=q.get('lhpay');
  if(!mode)return false;
  if(!state.user){toast('결제 결과 확인을 위해 다시 로그인해 주세요.');return true}
  if(mode==='fail'){
    const msg=q.get('message')||q.get('code')||'결제가 취소되었거나 실패했습니다.';
    history.replaceState({},'',location.pathname+location.hash);
    toast(msg);
    return true;
  }
  const paymentKey=q.get('paymentKey'),orderId=q.get('orderId'),amount=Number(q.get('amount')||0);
  if(!paymentKey||!orderId||!amount){
    history.replaceState({},'',location.pathname+location.hash);
    toast('결제 결과 정보가 올바르지 않습니다.');
    return true;
  }
  try{
    await marketplaceApi('confirm',{paymentKey,orderId,amount});
    history.replaceState({},'',location.pathname+location.hash);
    sessionStorage.removeItem('lifehelper.pay.bundleId');
    sessionStorage.removeItem('lifehelper.pay.reservationId');
    toast('결제가 완료되어 예약이 확정되었습니다.');
    setTimeout(openItinerary,150);
  }catch(e){
    console.error(e);
    history.replaceState({},'',location.pathname+location.hash);
    toast(e?.message||'결제 승인 확인에 실패했습니다.');
  }
  return true;
}
async function cancelPaidTrip(bundleId){
  const reason=String(prompt('취소 사유를 입력해 주세요.','일정 변경')||'').trim();
  if(!reason)return;
  if(!confirm('취소 정책을 확인하고 예약 취소 및 환불을 요청할까요?'))return;
  try{
    const r=await marketplaceApi('cancel',{bundle_id:bundleId,reason});
    toast(r.alreadyRefunded?'이미 환불 완료된 예약입니다.':'취소 및 환불 처리가 완료되었습니다.');
    openItinerary();
  }catch(e){
    console.error(e);
    if(e?.data?.error==='manual_review_required')toast('무료 취소 가능 기간이 지나 운영자 확인이 필요합니다.');
    else toast(e?.message||'취소 처리에 실패했습니다.');
  }
}
async function openItinerary(){if(!state.user)return openLogin();try{const [d,trips]=await Promise.all([itineraryApi('dashboard'),marketplaceApi('my_trips')]);const stays=d.stays||[],items=d.items||[],experiences=d.experiences||[],reservations=trips.reservations||[],bundles=trips.bundles||[];const resMap=new Map(reservations.map(r=>[r.id,r]));const bundleByReservation=new Map(bundles.map(b=>[b.reservation_id,b]));openModal(`<div><span class="eyebrow">MY KOREA</span><h2>내 일정</h2><p class="muted">확정 숙박·결제·체험 일정을 한곳에서 확인합니다.</p><h3>확정 숙박</h3>${stays.length?stays.map(s=>{const r=resMap.get(s.id)||s,b=bundleByReservation.get(s.id),paid=r.payment_status==='paid'||!!b?.paid_at,refunded=r.payment_status==='refunded'||b?.status==='refunded';return `<article class="panel" style="margin-top:10px"><div class="panelHead"><div><b>🏨 ${s.spaces?.name||'확정 숙소'}</b><p class="muted small">${s.checkin||s.preferred_date||'—'} → ${s.checkout||'—'} · ${s.spaces?.location||''}</p></div><span class="status ${refunded?'cancelled':paid?'confirmed':'negotiating'}">${refunded?'환불완료':paid?'결제완료':'결제대기'}</span></div><p class="small">총 금액 <b>${money(r.total_amount)}</b></p><div class="cardActions">${!paid&&!refunded?`<button class="primary" data-pay-reservation="${s.id}">토스로 결제하기</button>`:''}${paid&&b&&!refunded?`<button data-cancel-bundle="${b.id}">예약 취소·환불</button>`:''}</div></article>`}).join(''):'<div class="empty"><p>아직 확정된 숙박이 없습니다.</p></div>'}<h3 style="margin-top:18px">체험 일정</h3>${items.filter(x=>x.item_type==='experience').length?items.filter(x=>x.item_type==='experience').map(x=>`<article class="panel" style="margin-top:10px"><div class="panelHead"><div><b>📷 ${x.meta?.title||'체험 일정'}</b><p class="muted small">${dateKo(x.starts_at)} · ${x.location_name||'장소 확인 중'}</p></div><button class="miniBtn" data-remove-itinerary="${x.id}">일정에서 제거</button></div><p class="modeNotice">${x.meta?.notice||'일정에 담긴 항목입니다. 예약확정 여부는 별도로 확인해 주세요.'}</p></article>`).join(''):'<div class="empty"><p>아직 추가한 체험 일정이 없습니다.</p></div>'}<h3 style="margin-top:18px">추가 가능한 체험</h3>${experiences.length?experiences.map(e=>`<article class="panel" style="margin-top:10px"><div class="panelHead"><div><b>${e.title}</b><p class="muted small">${e.location_name||'장소 협의'} · ${money(e.price_krw)}</p></div></div><p class="small">${e.summary||''}</p>${(e.slots||[]).slice(0,3).map(s=>`<button class="miniBtn primary" style="margin:4px" data-add-exp="${e.id}" data-slot="${s.id}">${new Date(s.starts_at).toLocaleString('ko-KR')} · ${s.group_status==='confirmed'||s.guaranteed_to_run?'진행확정':'모집중'} · 잔여 ${Math.max(0,Number(s.capacity||0)-Number(s.booked_count||0))}석 · 일정에 담기</button>`).join('')}</article>`).join(''):'<div class="empty"><div><b>현재 공개된 체험 회차가 없습니다.</b><p>승인된 체험과 실제 예약 가능 회차가 등록되면 여기에 표시됩니다.</p></div></div>'}<p class="modeNotice" style="margin-top:16px">결제는 서버에서 금액을 다시 검증한 뒤 확정되며, 환불 가능 여부도 숙박·체험 취소정책을 서버에서 확인합니다.</p></div>`);$$('[data-pay-reservation]').forEach(b=>b.onclick=()=>startReservationPayment(b.dataset.payReservation));$$('[data-cancel-bundle]').forEach(b=>b.onclick=()=>cancelPaidTrip(b.dataset.cancelBundle));$$('[data-add-exp]').forEach(b=>b.onclick=async()=>{try{await itineraryApi('add_experience',{experience_id:b.dataset.addExp,slot_id:b.dataset.slot});toast('체험을 내 일정에 담았습니다.');openItinerary()}catch{toast('체험 일정을 추가하지 못했습니다.')}});$$('[data-remove-itinerary]').forEach(b=>b.onclick=async()=>{try{await itineraryApi('remove_item',{item_id:b.dataset.removeItinerary});toast('일정에서 제거했습니다.');openItinerary()}catch{toast('일정을 변경하지 못했습니다.')}})}catch(e){console.error(e);toast('내 일정을 불러오지 못했습니다.')}}
async function openProposals(requestId){try{const manage_token=localStorage.getItem('lifehelper.request.'+requestId)||'';const r=await api('request_proposals',{request_id:requestId,manage_token});const ps=r.proposals||[];openModal(`<div><span class="eyebrow">STAY PROPOSALS</span><h2>숙소 제안</h2>${ps.length?ps.map(p=>`<article class="spaceCard" style="margin-top:12px"><div class="spaceImg" style="background-image:url('${p.spaces?.thumbnail_url||p.spaces?.photo_urls?.[0]||'https://images.unsplash.com/photo-1566665797739-1674de7a421a?auto=format&fit=crop&w=900&q=80'}')"></div><div class="spaceBody"><h3>${p.spaces?.name||'제안 숙소'}</h3><p class="muted">${p.spaces?.location||''}</p><div class="spaceMeta"><span>1박 <b>${money(p.nightly_rate)}</b></span><span>총 견적 <b>${money(p.total_quote)}</b></span><span>최대 <b>${p.max_guests||p.spaces?.capacity||'—'}명</b></span><span>예약방식 <b>${p.booking_method==='instant'?'즉시':p.booking_method==='contract'?'협의·계약':'요청 후 확정'}</b></span><span>재고확인 <b>${dateKo(p.inventory_checked_at)}</b></span><span>취소조건 <b>${p.cancellation_summary||'확인 필요'}</b></span></div><p>${p.message||''}</p>${p.status==='accepted'?`<div class="modeNotice">제안 조건 확인이 완료되어 현재 예약 협의 중입니다. 예약확정 전 최종 상태를 다시 안내합니다.</div>`:`<label class="consent"><input type="checkbox" data-terms="${p.id}">제안 금액·예약 방식·취소/환불 요약을 확인했고 예약 협의 진행에 동의합니다.</label><label class="consent"><input type="checkbox" data-privacy="${p.id}">예약 협의와 확정을 위해 입력 정보 처리에 동의합니다.</label>${r.purpose==='medical'?`<label class="consent"><input type="checkbox" data-medical="${p.id}">라이프헬퍼는 숙박 연결만 제공하며 의료기관 선택·진료 알선을 제공하지 않음을 확인했습니다.</label>`:''}<button class="primaryBtn" data-accept-proposal="${p.id}" data-request="${requestId}" data-purpose="${r.purpose||''}">이 제안으로 예약 협의하기</button>`}</div></article>`).join(''):'<div class="empty"><div><b>아직 도착한 숙소 제안이 없습니다.</b><p>운영자가 실제 재고와 조건을 확인 중입니다.</p></div></div>'}</div>`);$$('[data-accept-proposal]').forEach(b=>b.onclick=async()=>{try{const pid=b.dataset.acceptProposal;const terms=$(`[data-terms="${pid}"]`)?.checked===true,privacy=$(`[data-privacy="${pid}"]`)?.checked===true,medical=$(`[data-medical="${pid}"]`)?.checked===true;if(!terms||!privacy)return toast('제안 조건과 개인정보 처리 확인에 동의해 주세요.');const purpose=b.dataset.purpose;if(purpose==='medical'&&!medical)return toast('의료 목적 체류 안내를 확인해 주세요.');await api('accept_proposal',{proposal_id:pid,manage_token,terms_accepted:terms,privacy_accepted:privacy,medical_disclaimer_accepted:medical});toast('예약 협의 단계로 이동했습니다.');closeModal();openMyJourney()}catch{toast('제안을 선택하지 못했습니다.')}})}catch(e){toast('숙소 제안을 불러오지 못했습니다.')}}
function bindUser(){const form=$('#stayForm');if(!form)return;const today=new Date().toISOString().slice(0,10);form.check_in.min=today;form.check_out.min=today;form.check_in.addEventListener('change',()=>{form.check_out.min=form.check_in.value||today;if(form.check_out.value&&form.check_out.value<=form.check_in.value)form.check_out.value=''});$$('[data-purpose]').forEach(b=>b.onclick=()=>{state.purpose=b.dataset.purpose;form.purpose.value=state.purpose;$$('[data-purpose]').forEach(x=>x.classList.toggle('active',x.dataset.purpose===state.purpose));renderSpaces()});$$('[data-lang]').forEach(b=>b.onclick=()=>b.classList.toggle('active'));['guests','area'].forEach(n=>form[n].addEventListener('input',renderSpaces));form.onsubmit=submitStayForm;$('#myJourneyBtn').onclick=openMyJourney;$('#b2bHero').onclick=openPublicB2B;renderSpaces()}
function renderUser(){main.innerHTML=`<div class="page">${heroUser()}${purposeSection()}${requestBuilder()}${trustStrip()}${footer()}</div>`;bindUser()}
async function renderHost(){if(!state.user){main.innerHTML=`<div class="dashboard"><div class="dashHero"><div class="dashIntro"><span class="eyebrow">HOST MODE</span><h1>행사 수요가 숙소 매출이 되게.</h1><p>비어 있는 객실에 목적이 확실한 고객을 연결합니다.</p></div><div class="roleBox"><span>로그인 필요</span><b>호스트 기능은 로그인 후 사용합니다.</b><button class="secondaryBtn" id="hostLogin" style="margin-top:14px">로그인</button></div></div>${trustStrip()}</div>${footer()}`;$('#hostLogin').onclick=openLogin;return}main.innerHTML='<div class="loading">호스트 데이터를 확인하는 중입니다.</div>';try{state.hostData=await api('host_dashboard');drawHostDashboard()}catch(e){if(e.status===403){main.innerHTML=`<div class="dashboard"><div class="dashHero"><div class="dashIntro"><span class="eyebrow">HOST MODE</span><h1>첫 숙소를 등록하면 호스트 모드가 열립니다.</h1><p>기존 계정과 Helper ID는 그대로 사용하고, 숙소 등록 후 운영자 검토를 거칩니다.</p><button class="primaryBtn" id="firstSpaceBtn" style="margin-top:18px">객실 등록 시작</button></div><div class="roleBox"><span>현재 권한</span><b>일반 사용자</b><small>숙소를 보유한 계정은 자동으로 호스트 기능을 사용할 수 있습니다.</small></div></div></div>${footer()}`;$('#firstSpaceBtn').onclick=()=>openRoleApplication('host')}else{main.innerHTML='<div class="loading">호스트 데이터를 불러오지 못했습니다.</div>'}}}
function drawHostDashboard(){const d=state.hostData||{spaces:[],requests:[],proposals:[],reservations:[]};const confirmed=(d.reservations||[]).filter(x=>x.status==='confirmed').length;main.innerHTML=`<div class="dashboard"><div class="dashHero"><div class="dashIntro"><span class="eyebrow">HOST MODE</span><h1>수요를 빠르게 예약으로 연결하세요.</h1><p>객실 등록·내 숙소·숙박 요청·제안·예약 일정을 한 흐름으로 관리합니다.</p></div><div class="roleBox"><span>이번 주 핵심</span><b>${d.requests.length}건의 목적형 수요</b><small>답변이 필요한 요청부터 제안하세요.</small></div></div><div class="statGrid"><div class="stat"><span>내 숙소</span><b>${d.spaces.length}</b></div><div class="stat"><span>숙박 요청</span><b>${d.requests.length}</b></div><div class="stat"><span>보낸 제안</span><b>${d.proposals.length}</b></div><div class="stat"><span>예약 확정</span><b>${confirmed}</b></div><div class="stat"><span>다가오는 일정</span><b>${(d.reservations||[]).filter(x=>x.checkin&&new Date(x.checkin)>=new Date()).length}</b></div></div><div class="dashGrid"><section class="panel"><div class="panelHead"><h2>객실 등록 / 내 숙소</h2><button id="addSpaceBtn" class="miniBtn primary">+ 객실 등록</button></div>${d.spaces.length?d.spaces.map(s=>`<article class="spaceCard" style="grid-template-columns:110px 1fr;margin-top:10px"><div class="spaceImg" style="min-height:90px;background-image:url('${s.thumbnail_url||s.photo_urls?.[0]||'https://images.unsplash.com/photo-1566665797739-1674de7a421a?auto=format&fit=crop&w=500&q=75'}')"></div><div class="spaceBody"><div class="spaceTop"><h3>${s.name}</h3><span class="badge ${s.status==='approved'?'good':'warn'}">${s.status==='approved'?'승인':'검토중'}</span></div><p class="muted small">${s.location||''} · 최대 ${s.capacity||'—'}명 · ${money(s.per_person_price)}</p><div class="badges"><span class="badge ${s.inventory_verified_at?'good':'warn'}">${s.inventory_verified_at?'재고확인 기록':'재고 확인 필요'}</span>${s.allows_long_stay?'<span class="badge blue">장기숙박</span>':''}</div></div></article>`).join(''):'<div class="empty"><p>등록한 숙소가 없습니다.</p></div>'}</section><section class="panel"><div class="panelHead"><h2>숙박 요청</h2><span class="muted small">답변 → 제안 → 예약</span></div>${d.requests.length?d.requests.map(r=>`<article class="panel" style="box-shadow:none;margin-top:9px"><div class="panelHead"><div><b>${purposeLabel(r.purpose)} · ${r.guests}명</b><p class="muted small">${r.area||'지역 협의'} · ${r.check_in} → ${r.check_out}</p></div><span class="status ${r.status}">${statusText(r.status)}</span></div><p class="small">${r.room_needs||r.special_requests||'추가 요청 없음'}</p><div class="cardActions"><button class="primary" data-propose="${r.id}">제안 보내기</button></div></article>`).join(''):'<div class="empty"><p>현재 조건에 맞는 숙박 요청이 없습니다.</p></div>'}</section><section class="panel span2"><div class="panelHead"><h2>제안 관리 · 예약 일정</h2><span class="muted small">예약 확정 여부를 구분해서 봅니다.</span></div><div class="tableWrap"><table class="table"><thead><tr><th>구분</th><th>숙소/요청</th><th>기간</th><th>금액</th><th>상태</th></tr></thead><tbody>${(d.proposals||[]).map(p=>`<tr><td>제안</td><td>${p.spaces?.name||'숙소'} · ${purposeLabel(p.life_stay_requests?.purpose||'')}</td><td>${p.life_stay_requests?.check_in||'—'} → ${p.life_stay_requests?.check_out||'—'}</td><td>${money(p.total_quote)}</td><td><span class="status ${p.status==='accepted'?'negotiating':'proposing'}">${p.status==='accepted'?'수락·협의':'제안 '+p.status}</span></td></tr>`).join('')}${(d.reservations||[]).map(r=>`<tr><td>예약</td><td>${d.spaces.find(s=>s.id===r.space_id)?.name||'숙소'}</td><td>${r.checkin||r.preferred_date||'—'} → ${r.checkout||'—'}</td><td>${money(r.total_amount)}</td><td><span class="status ${r.status==='confirmed'?'confirmed':'proposing'}">${r.status}</span></td></tr>`).join('')}</tbody></table></div></section></div></div>${trustStrip()}${footer()}`;$('#addSpaceBtn').onclick=openSpaceRegistration;$$('[data-propose]').forEach(b=>b.onclick=()=>openProposalForm(b.dataset.propose))}
function openSpaceRegistration(){if(!state.user)return openLogin();openModal(`<div><span class="eyebrow">ROOM REGISTRATION</span><h2>객실 등록</h2><p class="muted">등록 후 운영자 검토와 재고 확인을 거쳐 공개됩니다.</p><form id="spaceRegisterForm" class="formGrid"><div class="field"><label>숙소명 *</label><input name="name" required></div><div class="field"><label>숙소 유형 *</label><select name="type"><option value="nightly">숙박</option><option value="nightly_rental">숙박+장기</option><option value="rental">장기숙박</option></select></div><div class="field"><label>지역 *</label><input name="location" placeholder="예: 서울 중구" required></div><div class="field"><label>주소 *</label><input name="address" required></div><div class="field"><label>객실 수</label><input name="room_count" type="number" min="1"></div><div class="field"><label>객실 유형</label><input name="room_type" placeholder="예: 더블/트윈"></div><div class="field"><label>최대 수용인원 *</label><input name="capacity" type="number" min="1" required></div><div class="field"><label>1인 1박 가격</label><input name="per_person_price" inputmode="numeric"></div><div class="field"><label>지원 언어</label><input name="languages" placeholder="ko,en,ja"></div><div class="field"><label>가능 기간 시작</label><input name="available_from" type="date"></div><div class="field full"><label>시설</label><input name="amenities" placeholder="Wi-Fi, 조식, 주방, 엘리베이터"></div><div class="field full"><label>숙소 설명</label><textarea name="description"></textarea></div><div class="field"><label>단체 가능</label><select name="allows_group"><option value="false">문의</option><option value="true">가능</option></select></div><div class="field"><label>장기숙박 가능</label><select name="allows_long_stay"><option value="false">불가/문의</option><option value="true">가능</option></select></div><div class="field"><label>예약 방식</label><select name="booking_mode"><option value="request">요청 후 확정</option><option value="contract">협의·계약</option><option value="instant">즉시 예약</option></select></div><div class="field"><label>대표 사진</label><input name="photo" type="file" accept="image/*"></div><div class="field full"><label>검증자료(숙박업 신고증 등)</label><input name="license" type="file" accept="image/*,.pdf"></div><div class="field full"><button class="submitBtn" type="submit">검토 요청하기</button></div></form></div>`);$('#spaceRegisterForm').onsubmit=submitSpaceRegistration}
async function submitSpaceRegistration(e){e.preventDefault();const f=new FormData(e.currentTarget);const slug='life-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);let photoUrl=null,licenseUrl=null;try{const photo=f.get('photo');if(photo&&photo.size){const path=`spaces/${state.user.id}/${crypto.randomUUID()}-${photo.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const u=await sb.storage.from('space-photos').upload(path,photo,{upsert:false});if(u.error)throw u.error;photoUrl=sb.storage.from('space-photos').getPublicUrl(path).data.publicUrl}const license=f.get('license');if(license&&license.size){const path=`lifehelper/${state.user.id}/spaces/${crypto.randomUUID()}-${license.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const u=await sb.storage.from('listing-uploads').upload(path,license,{upsert:false});if(u.error)throw u.error;licenseUrl='listing-uploads:'+path}const row={host_id:state.user.id,name:String(f.get('name')),slug,type:String(f.get('type')),location:String(f.get('location')),address:String(f.get('address')),description:String(f.get('description')||''),capacity:Number(f.get('capacity')||1),amenities:String(f.get('amenities')||'').split(',').map(x=>x.trim()).filter(Boolean),status:'pending',is_active:false,is_visible:false,photo_urls:photoUrl?[photoUrl]:[],thumbnail_url:photoUrl,room_count:Number(f.get('room_count')||0)||null,room_type:String(f.get('room_type')||'')||null,allows_group:f.get('allows_group')==='true',allows_long_stay:f.get('allows_long_stay')==='true',booking_mode:String(f.get('booking_mode')),supported_languages:String(f.get('languages')||'ko').split(',').map(x=>x.trim()).filter(Boolean),per_person_price:Number(f.get('per_person_price')||0)||150000,lodging_license_doc_url:licenseUrl};const {error}=await sb.from('spaces').insert(row);if(error)throw error;toast('숙소 등록이 접수되었습니다. 운영자 검토 후 공개됩니다.');closeModal();await refreshSession();if(canUseMode('host'))switchMode('host');else render()}catch(err){console.error(err);toast('숙소 등록에 실패했습니다. 입력값과 파일을 확인해 주세요.')}}
function openProposalForm(requestId){const d=state.hostData||{spaces:[]};if(!d.spaces.length)return toast('먼저 숙소를 등록해 주세요.');openModal(`<div><span class="eyebrow">SEND PROPOSAL</span><h2>숙소 제안 보내기</h2><form id="proposalForm" class="formGrid"><div class="field full"><label>제안 숙소 *</label><select name="space_id">${d.spaces.map(s=>`<option value="${s.id}">${s.name} · ${s.location||''}</option>`).join('')}</select></div><div class="field"><label>1박 가격</label><input name="nightly_rate" inputmode="numeric"></div><div class="field"><label>총 견적</label><input name="total_quote" inputmode="numeric"></div><div class="field"><label>객실 유형</label><input name="room_type" placeholder="예: 트윈룸"></div><div class="field"><label>최대 수용인원</label><input name="max_guests" type="number" min="1"></div><div class="field"><label>예약 방식</label><select name="booking_method"><option value="request">요청 후 확정</option><option value="contract">협의·계약</option><option value="instant">즉시 예약</option></select></div><div class="field full"><label>취소·환불 요약</label><input name="cancellation_summary" placeholder="예: 체크인 7일 전까지 무료취소"></div><div class="field full"><label>제안 메시지</label><textarea name="message" placeholder="객실 구성, 제공 서비스, 확인이 필요한 조건을 적어주세요."></textarea></div><div class="field full"><button class="submitBtn" type="submit">제안 보내기</button></div></form></div>`);$('#proposalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const payload={request_id:requestId,space_id:String(f.get('space_id')),nightly_rate:Number(f.get('nightly_rate')||0)||null,total_quote:Number(f.get('total_quote')||0)||null,room_type:String(f.get('room_type')||''),max_guests:Number(f.get('max_guests')||0)||null,booking_method:String(f.get('booking_method')),cancellation_summary:String(f.get('cancellation_summary')||''),message:String(f.get('message')||'')};try{await api('send_proposal',{payload});toast('숙소 제안을 보냈습니다.');closeModal();state.hostData=await api('host_dashboard');drawHostDashboard()}catch(err){toast('제안을 보내지 못했습니다.')}}}
function openSupplierApplication(){if(!state.user)return openLogin();openModal(`<div><span class="eyebrow">SUPPLIER APPLICATION</span><h2>공급자 등록 신청</h2><p class="muted">신청 후 운영자 검증이 완료되면 공급자 모드가 활성화됩니다.</p><form id="supplierApplyForm" class="formGrid"><div class="field"><label>브랜드명 *</label><input name="brand_name" required></div><div class="field"><label>담당자 *</label><input name="contact_name" required></div><div class="field"><label>연락처</label><input name="phone"></div><div class="field"><label>이메일</label><input name="email" type="email"></div><div class="field"><label>카테고리 *</label><select name="category"><option value="stay">숙소</option><option value="experience">체험</option><option value="local_service">지역 서비스</option></select></div><div class="field"><label>지역</label><input name="region"></div><div class="field"><label>최소 인원</label><input name="min_guests" type="number" min="1"></div><div class="field"><label>최대 인원</label><input name="max_guests" type="number" min="1"></div><div class="field"><label>기준 가격</label><input name="price_krw" inputmode="numeric"></div><div class="field"><label>지원 언어</label><input name="languages" value="ko"></div><div class="field"><label>숙소 제공</label><select name="can_host"><option value="false">아니오</option><option value="true">가능</option></select></div><div class="field"><label>출장 가능</label><select name="can_travel"><option value="false">아니오</option><option value="true">가능</option></select></div><div class="field full"><label>서비스 설명</label><textarea name="description"></textarea></div><div class="field full"><label>검증자료</label><input name="documents" type="file" multiple accept="image/*,.pdf"></div><div class="field full"><button class="submitBtn" type="submit">검토 요청하기</button></div></form></div>`);$('#supplierApplyForm').onsubmit=submitSupplier}
function renderSupplier(){main.innerHTML=`<div class="dashboard"><div class="dashHero"><div class="dashIntro"><span class="eyebrow">SUPPLIER · B2B</span><h1>숙박 파트너, 체험 제공자, 단체 수요를 하나로.</h1><p>공급자 등록부터 기업·단체 견적 요청까지 실제 데이터로 접수합니다.</p></div><div class="roleBox"><span>공급 생태계</span><b>검증 → 매칭 → 제안 → 예약</b><small>공급자 정보는 승인 전 고객에게 공개하지 않습니다.</small></div></div><div class="supplierLayout"><section class="panel"><div class="panelHead"><h2>공급자 등록</h2><span class="badge warn">검증 후 공개</span></div><form id="supplierForm" class="formGrid"><div class="field"><label>브랜드명 *</label><input name="brand_name" required></div><div class="field"><label>담당자 *</label><input name="contact_name" required></div><div class="field"><label>연락처</label><input name="phone"></div><div class="field"><label>이메일</label><input name="email" type="email"></div><div class="field"><label>카테고리 *</label><select name="category"><option value="stay">숙소</option><option value="experience">체험</option><option value="local_service">지역 서비스</option></select></div><div class="field"><label>지역</label><input name="region"></div><div class="field"><label>최소 인원</label><input name="min_guests" type="number" min="1"></div><div class="field"><label>최대 인원</label><input name="max_guests" type="number" min="1"></div><div class="field"><label>기준 가격</label><input name="price_krw" inputmode="numeric"></div><div class="field"><label>지원 언어</label><input name="languages" placeholder="ko,en,ja"></div><div class="field"><label>숙소 제공</label><select name="can_host"><option value="false">아니오</option><option value="true">가능</option></select></div><div class="field"><label>출장 가능</label><select name="can_travel"><option value="false">아니오</option><option value="true">가능</option></select></div><div class="field full"><label>서비스 설명</label><textarea name="description"></textarea></div><div class="field full"><label>검증자료</label><input name="documents" type="file" multiple accept="image/*,.pdf"><span class="muted small">로그인한 공급자만 비공개 자료 첨부가 가능합니다.</span></div><div class="field full"><button class="submitBtn" type="submit">공급자 검토 요청</button></div></form></section><section class="panel"><div class="panelHead"><h2>기업·단체 견적</h2><span class="badge blue">24시간 내 조건 확인 목표</span></div><form id="b2bForm" class="formGrid"><div class="field"><label>기업/단체명 *</label><input name="company_name" required></div><div class="field"><label>행사명</label><input name="event_name"></div><div class="field"><label>담당자 *</label><input name="contact_name" required></div><div class="field"><label>전화 *</label><input name="phone" required></div><div class="field"><label>이메일 *</label><input name="email" type="email" required></div><div class="field"><label>방문 목적</label><select name="purpose">${purposes.map(p=>`<option value="${p.id}">${p.ko}</option>`).join('')}</select></div><div class="field"><label>시작일 *</label><input name="start_date" type="date" required></div><div class="field"><label>종료일 *</label><input name="end_date" type="date" required></div><div class="field"><label>인원 *</label><input name="group_size" type="number" min="1" max="5000" required></div><div class="field"><label>1인 예산</label><input name="budget_per_person" inputmode="numeric"></div><div class="field"><label>지역</label><input name="area"></div><div class="field"><label>국가/언어</label><input name="country_language"></div><div class="field full"><label>원하는 서비스</label><div class="checkRow"><button type="button" class="chipCheck active" data-service="stay">숙소</button><button type="button" class="chipCheck" data-service="experience">체험</button><button type="button" class="chipCheck" data-service="transport">이동</button><button type="button" class="chipCheck" data-service="local_service">지역서비스</button></div></div><div class="field full"><label>추가 요청</label><textarea name="notes"></textarea></div><div class="field full"><label class="consent"><input type="checkbox" name="b2b_consent" required>단체 견적 상담을 위해 입력한 담당자 정보를 처리하는 데 동의합니다.</label></div><div class="field full"><button class="submitBtn" type="submit">견적 요청하기 →</button></div></form></section></div><section class="panel" style="margin-top:18px"><div class="panelHead"><h2>단체·기업 견적 흐름</h2></div><div class="flow"><div class="flowStep"><b>1</b>견적 요청<span>조건 입력</span></div><div class="flowStep"><b>2</b>인원·예산 확인<span>운영자 검토</span></div><div class="flowStep"><b>3</b>공급자 매칭<span>실재고 확인</span></div><div class="flowStep"><b>4</b>맞춤 제안<span>비용·조건 합의</span></div><div class="flowStep"><b>5</b>예약 진행<span>확정 상태 관리</span></div></div></section></div>${trustStrip()}${footer()}`;bindSupplier()}
async function bindSupplier(){$$('#supplierForm [name=documents]');$('#supplierForm').onsubmit=submitSupplier;$$('[data-service]').forEach(b=>b.onclick=()=>b.classList.toggle('active'));$('#b2bForm').onsubmit=submitB2B;if(state.user&&state.roles.includes('supplier')){const wrap=document.createElement('section');wrap.className='panel';wrap.style.marginTop='18px';wrap.innerHTML='<div class="panelHead"><div><h2>체험 운영</h2><p class="muted small">체험·회차·최소인원 모집상태 관리</p></div><button id="experienceOpsBtn" class="miniBtn primary">체험 운영 열기</button></div>';const base=document.querySelector('.supplierLayout');if(base)base.after(wrap);$('#experienceOpsBtn').onclick=openExperienceOps}}
async function openExperienceOps(){try{const d=await partnerApi('dashboard'),ex=d.experiences||[],slots=d.slots||[],bookings=d.bookings||[];let html='<div><span class="eyebrow">EXPERIENCE OPS</span><h2>체험 운영</h2><div class="statGrid"><div class="stat"><span>체험</span><b>'+ex.length+'</b></div><div class="stat"><span>회차</span><b>'+slots.length+'</b></div><div class="stat"><span>모집중</span><b>'+slots.filter(s=>s.group_status==='recruiting').length+'</b></div><div class="stat"><span>진행확정</span><b>'+slots.filter(s=>s.group_status==='confirmed').length+'</b></div></div><div class="cardActions" style="margin:14px 0"><button id="newExpBtn" class="primary">+ 체험 등록</button></div>';html+=ex.map(e=>{const es=slots.filter(s=>s.experience_id===e.id);return '<article class="panel" style="box-shadow:none;margin-top:10px"><div class="panelHead"><div><b>'+e.title+'</b><p class="muted small">최소 '+(e.min_guests||1)+'명 · 최대 '+(e.max_guests||'—')+'명 · '+money(e.price_krw)+'</p></div><span class="badge '+(e.status==='approved'?'good':'warn')+'">'+e.status+'</span></div>'+((es.length?es.map(s=>'<p class="small">'+new Date(s.starts_at).toLocaleString('ko-KR')+' · '+(s.group_status==='confirmed'?'진행확정':'모집중')+' · '+(s.booked_count||0)+'/'+(s.min_guests_override||e.min_guests||1)+'명 · 잔여 '+Math.max(0,Number(s.capacity||0)-Number(s.booked_count||0))+'석</p>').join(''):'<p class="muted small">등록된 회차 없음</p>'))+'<div class="cardActions"><button data-add-exp-slot="'+e.id+'">+ 회차 추가</button>'+(e.status!=='approved'?'<button data-publish-exp="'+e.id+'">공개 검토 요청</button>':'')+'</div></article>'}).join('');html+='<h3 style="margin-top:16px">최근 예약</h3>'+(bookings.slice(0,8).map(b=>'<p class="small">'+(b.experiences?.title||'체험')+' · '+b.guest_count+'명 · '+(b.group_status==='confirmed'?'진행확정':'모집중')+'</p>').join('')||'<p class="muted small">예약 내역 없음</p>')+'</div>';openModal(html);$('#newExpBtn').onclick=createExperienceQuick;$$('[data-add-exp-slot]').forEach(b=>b.onclick=()=>createExperienceSlotQuick(b.dataset.addExpSlot));$$('[data-publish-exp]').forEach(b=>b.onclick=async()=>{try{await partnerApi('request_publish',{experience_id:b.dataset.publishExp});toast('공개 검토를 요청했습니다.');openExperienceOps()}catch(e){toast(e?.message||'검토 요청 실패')}})}catch(e){console.error(e);toast(e?.message||'체험 운영 데이터를 불러오지 못했습니다.')}}
async function createExperienceQuick(){const title=String(prompt('체험명을 입력해 주세요.','')||'').trim();if(!title)return;const location_name=String(prompt('지역/장소를 입력해 주세요.','서울')||'').trim();const price_krw=Number(prompt('1인 가격(원)','50000')||0);const min_guests=Number(prompt('최소 진행 인원','2')||2);const max_guests=Number(prompt('최대 인원','10')||10);if(min_guests<1||max_guests<min_guests)return toast('최소/최대 인원을 확인해 주세요.');try{await partnerApi('save_experience',{payload:{title,category:'culture',location_name,price_krw,min_guests,max_guests,duration_minutes:120,confirmation_mode:'group_minimum',languages:['ko','en'],summary:''}});toast('체험을 저장했습니다.');openExperienceOps()}catch(e){toast(e?.message||'체험 저장 실패')}}
async function createExperienceSlotQuick(experienceId){const starts_at=String(prompt('시작 시각 (예: 2026-10-05T14:00)','')||'').trim();if(!starts_at)return;const ends_at=String(prompt('종료 시각 (예: 2026-10-05T16:00)','')||'').trim();const capacity=Number(prompt('정원','10')||10);if(!ends_at||new Date(ends_at)<=new Date(starts_at)||capacity<1)return toast('회차 시간과 정원을 확인해 주세요.');try{await partnerApi('add_slot',{experience_id:experienceId,starts_at,ends_at,capacity});toast('회차를 추가했습니다.');openExperienceOps()}catch(e){toast(e?.message||'회차 추가 실패')}}
async function submitSupplier(e){e.preventDefault();const f=new FormData(e.currentTarget),docs=[];try{const files=Array.from(f.getAll('documents')).filter(x=>x&&x.size);if(files.length&&!state.user){toast('검증자료 첨부는 로그인 후 가능합니다.');return openLogin()}for(const file of files.slice(0,6)){const path=`lifehelper/${state.user.id}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await sb.storage.from('listing-uploads').upload(path,file,{upsert:false});if(up.error)throw up.error;docs.push({bucket:'listing-uploads',path,name:file.name})}const payload={brand_name:String(f.get('brand_name')),contact_name:String(f.get('contact_name')),phone:String(f.get('phone')||''),email:String(f.get('email')||''),category:String(f.get('category')),region:String(f.get('region')||''),min_guests:Number(f.get('min_guests')||0)||null,max_guests:Number(f.get('max_guests')||0)||null,price_krw:Number(f.get('price_krw')||0)||null,languages:String(f.get('languages')||'ko').split(',').map(x=>x.trim()).filter(Boolean),can_host:f.get('can_host')==='true',can_travel:f.get('can_travel')==='true',description:String(f.get('description')||''),verification_documents:docs};const r=await api('supplier_register',{payload});toast(`공급자 등록이 접수되었습니다. 상태: ${r.supplier.verification_status}`);e.currentTarget.reset();await refreshSession()}catch(err){console.error(err);toast('공급자 등록에 실패했습니다.')}}
async function submitB2B(e){e.preventDefault();const f=new FormData(e.currentTarget),services=$$('[data-service].active').map(b=>b.dataset.service);if(!e.currentTarget.b2b_consent.checked)return toast('개인정보 처리 동의를 확인해 주세요.');const payload={privacy_accepted:true,helper_id:helperId(),company_name:String(f.get('company_name')),event_name:String(f.get('event_name')||''),contact_name:String(f.get('contact_name')),phone:String(f.get('phone')),email:String(f.get('email')),purpose:String(f.get('purpose')||''),start_date:String(f.get('start_date')),end_date:String(f.get('end_date')),group_size:Number(f.get('group_size')),budget_per_person:Number(f.get('budget_per_person')||0)||null,area:String(f.get('area')||''),country_language:String(f.get('country_language')||''),services,notes:String(f.get('notes')||'')};try{const r=await b2bApi(payload);toast('단체 견적 요청이 접수되었습니다.');openModal(`<div><span class="eyebrow">B2B REQUEST</span><h2>견적 요청이 접수됐습니다.</h2><p>요청번호 ${r.quote.id}</p><p class="modeNotice">조건 확인 → 공급자 매칭 → 맞춤 제안 → 예약 진행 순서로 처리합니다. 응답 목표 시각은 ${dateKo(r.quote.response_due_at)}입니다.</p></div>`);e.currentTarget.reset()}catch(err){toast('견적 요청을 저장하지 못했습니다.')}}
const OP_API_URL=SB_URL+'/functions/v1/lifehelper-v2-operator-api';
async function opApi(action,payload={}){const headers={'Content-Type':'application/json',apikey:SB_KEY};if(token())headers.Authorization='Bearer '+token();const r=await fetch(OP_API_URL,{method:'POST',headers,body:JSON.stringify({action,...payload})});const j=await r.json().catch(()=>({error:'invalid_response'}));if(!r.ok)throw Object.assign(new Error(j.message||j.error||'운영자 요청 실패'),{status:r.status,data:j});return j}
async function renderOperator(){if(!state.user){main.innerHTML=`<div class="dashboard"><div class="dashHero"><div class="dashIntro"><span class="eyebrow">OPERATOR MODE</span><h1>플랫폼의 신뢰·속도·전환율을 관리합니다.</h1><p>운영자 계정으로 로그인해야 요청·공급·예약 상태를 관리할 수 있습니다.</p></div><div class="roleBox"><span>권한 필요</span><b>운영자 전용</b><button class="secondaryBtn" id="operatorLogin" style="margin-top:14px">로그인</button></div></div></div>${footer()}`;$('#operatorLogin').onclick=openLogin;return}main.innerHTML='<div class="loading">운영자 데이터를 확인하는 중입니다.</div>';try{state.operatorData=await opApi('dashboard');drawOperator()}catch(e){main.innerHTML=`<div class="dashboard"><div class="modeNotice">현재 계정에는 운영자 권한이 없습니다. 기존 관리자 권한을 임의로 변경하지 않았습니다.</div></div>${footer()}`}}
function drawOperator(){const d=state.operatorData||{},rs=d.requests||[],spaces=d.spaces||[],suppliers=d.suppliers||[],reservations=d.reservations||[],props=d.proposals||[],b2b=d.b2b||[];const pendingSpaces=spaces.filter(x=>x.status==='pending').length,pendingSup=suppliers.filter(x=>['pending','reviewing'].includes(x.verification_status)).length,activeRes=reservations.filter(x=>['pending','consulting','confirmed','checked_in'].includes(x.status)).length,done=rs.filter(x=>x.status==='completed').length;main.innerHTML=`<div class="dashboard"><div class="dashHero"><div class="dashIntro"><span class="eyebrow">OPERATOR MODE</span><h1>요청·매칭·예약·공급자 품질을 한눈에.</h1><p>목적 선택부터 일정 완성까지 전환 흐름과 병목을 관리합니다.</p></div><div class="roleBox"><span>전체 전환율</span><b>${calcFunnelRate(d.funnel)}%</b><small>요청 기준 완료 비율 · 표본이 적으면 변동이 큽니다.</small></div></div><div class="statGrid"><div class="stat"><span>요청 대기</span><b>${rs.filter(x=>x.status==='requested').length}</b></div><div class="stat"><span>응답 지연</span><b>${d.delayed||0}</b></div><div class="stat"><span>숙소 승인 대기</span><b>${pendingSpaces}</b></div><div class="stat"><span>공급자 승인 대기</span><b>${pendingSup}</b></div><div class="stat"><span>진행 예약</span><b>${activeRes}</b></div><div class="stat"><span>체험 일정 추가</span><b>${d.experienceAdds||0}</b></div><div class="stat"><span>전체 일정 항목</span><b>${d.itineraryItems||0}</b></div></div><div class="dashGrid"><section class="panel"><div class="panelHead"><h2>숙박 요청 전환</h2><span class="muted small">요청접수 → 제안중 → 예약협의 → 예약확정 → 완료</span></div>${(d.funnel||[]).map((f,i)=>{const base=(d.funnel?.[0]?.count||0);const pct=base?Math.round(f.count/base*100):0;return `<div style="margin:12px 0"><div style="display:flex;justify-content:space-between"><b>${i+1}. ${statusText(f.status)}</b><span>${f.count}건 · ${pct}%</span></div><div style="height:8px;background:#eaf1f8;border-radius:99px;overflow:hidden"><i style="display:block;width:${pct}%;height:100%;background:#0b63e5"></i></div></div>`}).join('')}</section><section class="panel"><div class="panelHead"><h2>요청 관리</h2><span class="muted small">상태를 명확하게 유지합니다.</span></div><div class="tableWrap"><table class="table"><thead><tr><th>목적</th><th>일정</th><th>인원</th><th>지역</th><th>상태</th><th>변경</th></tr></thead><tbody>${rs.slice(0,30).map(r=>`<tr><td>${purposeLabel(r.purpose)}</td><td>${r.check_in}→${r.check_out}</td><td>${r.guests}</td><td>${r.area||'—'}</td><td><span class="status ${r.status}">${statusText(r.status)}</span></td><td><select class="miniBtn" data-request-status="${r.id}"><option value="requested" ${r.status==='requested'?'selected':''}>요청접수</option><option value="proposing" ${r.status==='proposing'?'selected':''}>제안중</option><option value="negotiating" ${r.status==='negotiating'?'selected':''}>예약협의</option><option value="confirmed" ${r.status==='confirmed'?'selected':''}>예약확정</option><option value="completed" ${r.status==='completed'?'selected':''}>완료</option><option value="cancelled" ${r.status==='cancelled'?'selected':''}>취소</option></select></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panelHead"><h2>숙소 승인</h2><span class="badge warn">검증 체크 후 공개</span></div>${spaces.filter(x=>x.status!=='approved'||!x.is_visible).slice(0,20).map(s=>`<article class="panel" style="box-shadow:none;margin-top:8px"><div class="panelHead"><div><b>${s.name}</b><p class="muted small">${s.location||''}</p></div><span class="status ${s.status==='approved'?'confirmed':'requested'}">${s.status}</span></div><p class="small">검증자료: ${s.lodging_license_doc_url?'제출됨':'미제출'} · 현재 공개 ${s.is_visible?'예':'아니오'}</p>${s.lodging_license_doc_url?`<button class="miniBtn" data-view-docs="${s.id}" data-doc-target="space">검증자료 보기</button>`:''}<label class="consent"><input type="checkbox" data-license-check="${s.id}" ${s.host_license_verified?'checked':''}>영업/숙박 관련 검증자료 확인</label><div class="cardActions"><button data-space-review="${s.id}" data-decision="review">검토 유지</button><button class="primary" data-space-review="${s.id}" data-decision="approve">승인·공개</button><button data-space-review="${s.id}" data-decision="reject">반려</button></div></article>`).join('')||'<div class="empty"><p>승인 대기 숙소가 없습니다.</p></div>'}</section><section class="panel"><div class="panelHead"><h2>공급자 검증</h2><span class="muted small">숙소·체험·지역서비스</span></div>${suppliers.slice(0,20).map(s=>`<article class="panel" style="box-shadow:none;margin-top:8px"><div class="panelHead"><div><b>${s.brand_name}</b><p class="muted small">${s.category} · ${s.region||'지역 미입력'}</p></div><span class="badge ${s.verification_status==='approved'?'good':'warn'}">${s.verification_status}</span></div><p class="small">검증자료 ${(s.verification_documents||[]).length}개 · ${s.description||''}</p>${(s.verification_documents||[]).length?`<button class="miniBtn" data-view-docs="${s.id}" data-doc-target="supplier">검증자료 보기</button>`:''}<div class="cardActions"><button data-supplier-review="${s.id}" data-status="reviewing">검토중</button><button class="primary" data-supplier-review="${s.id}" data-status="approved">승인</button><button data-supplier-review="${s.id}" data-status="rejected">반려</button></div></article>`).join('')||'<div class="empty"><p>공급자 신청이 없습니다.</p></div>'}</section><section class="panel span2"><div class="panelHead"><h2>수락 제안 → 예약 확정</h2><span class="muted small">조건 동의 후에만 확정 처리합니다.</span></div><div class="tableWrap"><table class="table"><thead><tr><th>숙소</th><th>목적/인원</th><th>일정</th><th>총 견적</th><th>제안상태</th><th>예약</th></tr></thead><tbody>${props.filter(p=>p.status==='accepted').map(p=>`<tr><td>${p.spaces?.name||'숙소'}</td><td>${purposeLabel(p.life_stay_requests?.purpose||'')} · ${p.life_stay_requests?.guests||'—'}명</td><td>${p.life_stay_requests?.check_in||'—'}→${p.life_stay_requests?.check_out||'—'}</td><td>${money(p.total_quote)}</td><td><span class="status negotiating">수락·협의</span></td><td><button class="miniBtn primary" data-confirm-proposal="${p.id}">예약 확정</button></td></tr>`).join('')||'<tr><td colspan="6">예약확정 대기 제안이 없습니다.</td></tr>'}</tbody></table></div></section><section class="panel span2"><div class="panelHead"><h2>기업·단체 견적</h2><span class="muted small">요청 → 검토 → 견적 → 수락</span></div><div class="tableWrap"><table class="table"><thead><tr><th>단체</th><th>행사</th><th>인원</th><th>일정</th><th>응답 목표</th><th>상태</th></tr></thead><tbody>${b2b.map(q=>`<tr><td>${q.company_name}</td><td>${q.event_name||'—'}</td><td>${q.group_size}</td><td>${q.start_date}→${q.end_date}</td><td>${dateKo(q.response_due_at)}</td><td><select class="miniBtn" data-b2b-status="${q.id}"><option value="new" ${q.status==='new'?'selected':''}>신규</option><option value="reviewing" ${q.status==='reviewing'?'selected':''}>검토중</option><option value="quoted" ${q.status==='quoted'?'selected':''}>견적완료</option><option value="accepted" ${q.status==='accepted'?'selected':''}>수락</option><option value="declined" ${q.status==='declined'?'selected':''}>거절</option></select></td></tr>`).join('')}</tbody></table></div></section></div></div>${trustStrip()}${footer()}`;bindOperator()}
function calcFunnelRate(f){const first=f?.[0]?.count||0,last=f?.[f.length-1]?.count||0;return first?Math.round(last/first*100):0}
function bindOperator(){$$('[data-view-docs]').forEach(b=>b.onclick=async()=>{try{const r=await opApi('signed_docs',{target:b.dataset.docTarget,id:b.dataset.viewDocs});const docs=r.documents||[];openModal(`<div><span class="eyebrow">PRIVATE VERIFICATION</span><h2>검증자료</h2><p class="modeNotice">아래 링크는 운영자 확인을 위한 임시 링크이며 외부 공유용이 아닙니다.</p>${docs.length?docs.map(d=>`<p><a class="primaryBtn" href="${d.url}" target="_blank" rel="noopener">${d.name||'자료 열기'}</a></p>`).join(''):'<p>열 수 있는 검증자료가 없습니다.</p>'}</div>`)}catch{toast('검증자료를 열지 못했습니다.')}});$$('[data-request-status]').forEach(s=>s.onchange=async()=>{try{await opApi('set_request_status',{request_id:s.dataset.requestStatus,status:s.value});toast('요청 상태를 변경했습니다.');state.operatorData=await opApi('dashboard');drawOperator()}catch{toast('상태 변경에 실패했습니다.')}});$$('[data-space-review]').forEach(b=>b.onclick=async()=>{const id=b.dataset.spaceReview,verified=$(`[data-license-check="${id}"]`)?.checked===true;try{const r=await opApi('review_space',{space_id:id,decision:b.dataset.decision,license_verified:verified});toast(r.public?'검증 확인 후 숙소를 공개했습니다.':'숙소 검토 상태를 변경했습니다.');state.operatorData=await opApi('dashboard');drawOperator()}catch{toast('숙소 검토 처리에 실패했습니다.')}});$$('[data-supplier-review]').forEach(b=>b.onclick=async()=>{try{await opApi('review_supplier',{supplier_id:b.dataset.supplierReview,status:b.dataset.status});toast('공급자 검토 상태를 변경했습니다.');state.operatorData=await opApi('dashboard');drawOperator()}catch{toast('공급자 검토 처리에 실패했습니다.')}});$$('[data-confirm-proposal]').forEach(b=>b.onclick=async()=>{if(!confirm('수락된 제안의 조건이 최종 확인되었나요? 예약확정 상태로 저장합니다.'))return;try{await opApi('confirm_reservation',{proposal_id:b.dataset.confirmProposal});toast('예약을 확정했습니다.');state.operatorData=await opApi('dashboard');drawOperator()}catch(err){toast('예약 확정에 실패했습니다.')}});$$('[data-b2b-status]').forEach(s=>s.onchange=async()=>{try{await opApi('update_b2b',{quote_id:s.dataset.b2bStatus,status:s.value});toast('B2B 견적 상태를 변경했습니다.')}catch{toast('견적 상태 변경에 실패했습니다.')}})}
async function bootstrap(){try{await refreshSession();const b=await api('bootstrap');state.spaces=b.spaces||[];if(b.user){state.roles=b.user.roles||state.roles;state.user={...state.user,...b.user}}await handleMarketplacePaymentReturn()}catch(err){console.error(err);state.spaces=[]}render()}
function render(){if(!canUseMode(state.mode))state.mode='user';syncTopbar();if(state.mode==='user')renderUser();else if(state.mode==='host')renderHost();else if(state.mode==='supplier')renderSupplier();else renderOperator()}
sb.auth.onAuthStateChange(async(event,session)=>{state.user=session?{...session.user,access_token:session.access_token}:null;if(['SIGNED_IN','SIGNED_OUT','TOKEN_REFRESHED','USER_UPDATED'].includes(event)){await refreshSession();try{const b=await api('bootstrap');state.spaces=b.spaces||[];if(b.user)state.roles=b.user.roles||['user']}catch{}render()}});
bootstrap();
